export function crearMapaModulo(deps){var DOM=deps.DOM;var getMAPA=deps.getMAPA;var uiState=deps.uiState;var obtenerRegistro=deps.obtenerRegistro;var leerFavoritos=deps.leerFavoritos;var DomPainter=deps.DomPainter;var cssEscape=deps.cssEscape;var slug=deps.slug;var MAPA_PADDING_GUIA_PX=deps.MAPA_PADDING_GUIA_PX;var MAPA_PADDING_EXPLORACION_PX=deps.MAPA_PADDING_EXPLORACION_PX;var motorMapa=null;function getMotorMapa(){return motorMapa}function resaltarTarjeta(id,activo){var previa=DOM.panelDescubrimiento.querySelector(".tarjeta--resaltada");if(previa)previa.classList.remove("tarjeta--resaltada");if(activo&&id){var el=DOM.panelDescubrimiento.querySelector('[data-lugar-id="'+cssEscape(id)+'"]');if(el)el.classList.add("tarjeta--resaltada")}}function inicializarMotorMapa(){if(motorMapa||!DOM.mapaHerramienta||!window.URU_MOTOR_MAPA_RENDER)return;try{motorMapa=window.URU_MOTOR_MAPA_RENDER.crear(DOM.mapaHerramienta,{lat:-32.4833,lng:-58.2333,zoom:14,ariaLabel:"Mapa de los resultados de tu búsqueda"});motorMapa.on("hover",function(punto){resaltarTarjeta(punto.id,true);if(window.AmbienteHalos)window.AmbienteHalos.mostrarEn(50,50)});motorMapa.on("hoverOut",function(){resaltarTarjeta(null,false);if(window.AmbienteHalos)window.AmbienteHalos.ocultar()});motorMapa.on("click",function(punto){var el=DOM.panelDescubrimiento.querySelector('[data-lugar-id="'+cssEscape(punto.id)+'"]');if(el){el.scrollIntoView({behavior:"smooth",block:"nearest"})}if(window.AmbienteCoordenadas)window.AmbienteCoordenadas.mostrarEn(50,50);if(window.AmbienteHalos)window.AmbienteHalos.mostrarEn(50,50)})}catch(e){console.error("Error al inicializar motor de mapa:",e);motorMapa=null}}function actualizarHerramienta(nombreRegion,lista){if(!DOM.mapaHerramienta)return;var MAPA=getMAPA();if(DOM.mapaContainer)DOM.mapaContainer.dataset.region=nombreRegion||"";var debeMostrar=MAPA.debeMostrarHerramienta(nombreRegion,lista);if(!debeMostrar){DOM.mapaHerramienta.hidden=true;if(DOM.mapaInfo)DOM.mapaInfo.hidden=true;if(DOM.mapaLeyenda)DOM.mapaLeyenda.hidden=true;if(DOM.mapaContainer)DOM.mapaContainer.hidden=true;return}if(DOM.mapaContainer)DOM.mapaContainer.hidden=false;DOM.mapaHerramienta.hidden=false;if(DOM.mapaInfo)DOM.mapaInfo.hidden=false;inicializarMotorMapa();if(!motorMapa)return;var conCoordenadas=lista.filter(function(l){return typeof l.lat==="number"&&typeof l.lng==="number"});var recorte=MAPA.puntosHerramienta(conCoordenadas);var favoritosActivos=leerFavoritos();var puntos=recorte.map(function(l){var meta=window.URU_RUBROS_META&&window.URU_RUBROS_META[l.grupo];var slugL=slug(l);return{id:l.id,lat:l.lat,lng:l.lng,nombre:l.nombre,direccion:l.direccion,href:slugL?"locales/"+slugL+"/":null,esFavorito:!!favoritosActivos[l.id],color:l.grupo&&window.URU_RUBROS_COLOR_RESUELTO?window.URU_RUBROS_COLOR_RESUELTO(l.grupo,"#C97A83"):"#C97A83",rubroNombre:meta?meta[0]:l.categoria,rubroKey:l.grupo,rubroIcono:meta?meta[3]:null}});motorMapa.establecerPuntos(puntos);motorMapa.encuadrarTodos(nombreRegion==="exploracion"?MAPA_PADDING_EXPLORACION_PX:MAPA_PADDING_GUIA_PX);if(uiState.cercaTuyoActivo&&uiState.ubicacionUsuario){motorMapa.establecerMarcadorUsuario(uiState.ubicacionUsuario)}else{motorMapa.quitarMarcadorUsuario()}DomPainter.pintarLeyenda(puntos);if(DOM.mapaInfo){DOM.mapaInfo.textContent=recorte.length<conCoordenadas.length?"Mostrando "+recorte.length+" de "+conCoordenadas.length+" lugares con ubicación en el mapa.":recorte.length+" lugar"+(recorte.length===1?"":"es")+" en el mapa."}}function actualizarTextura(){var MAPA=getMAPA();if(!DOM.mapaTextura||!obtenerRegistro().length)return;if(!window.URU_CONFIG.mapa.texturaSiempreVisible)return;if(DOM.mapaTextura.dataset.pintado==="1")return;var puntos=MAPA.puntosTextura(obtenerRegistro());var meta=window.URU_RUBROS_META||{};var frag=document.createDocumentFragment();var i=0;puntos.forEach(function(l){if(typeof l.lat!=="number"||typeof l.lng!=="number")return;var p=document.createElement("div");p.className="punto-textura";p.style.left=Math.random()*100+"%";p.style.top=Math.random()*100+"%";p.style.setProperty("--i",i);var colorRubro=meta[l.grupo]&&meta[l.grupo][2];if(colorRubro)p.style.setProperty("--dot-color",colorRubro);i++;frag.appendChild(p)});DOM.mapaTextura.appendChild(frag);DOM.mapaTextura.dataset.pintado="1"}return{actualizarHerramienta:actualizarHerramienta,actualizarTextura:actualizarTextura,getMotorMapa:getMotorMapa}}